acceso_token carga útil:
  { sub: user_id, jti: dispositivo_id, tipo: "yaykuna", exp: kunan + 15min }
refresh_token carga útil:
  { sub: user_id, jti: dispositivo_id, tipo: "musuqchay", exp: kunan + 30d }

HS256-firmasqa nodopa 64 byte pakasqa .env kaqmanta

rooms.h6_f:
