ciphertext = AES-GCM-Chifray(cuarto_llave, nonce, CBOR_payload, aad=cuarto_id)

Fan-out marco: { tipo:"m", cuarto, msg:{id, ct, nonce, kachaq_pseudo, kachasqa_kaypi} }

files.h2_f:
