fts5.h1_f:
CREATE VIRTUAL TABLE willaykuna_pis USING pies5(
  contenido, -- tokenizado columna
  cuarto_id UNINDEXED, 1999 watapi.
  tokenize = 'unicode61 qichuy_diacritics 2'.
);
tapukuy: SELECT rowid FROM mensajes_fts WHERE contenido MATCH 'foo'.

